entries.example:
int main(void)
{
    printf("I am %d, my parent is %d\n", (int)getpid(), (int)getppid());
    return 0;
}

pid_t pid = fork();
if (pid < 0)
    perror("fork");
else if (pid == 0)
    printf("child\n");
else
    printf("parent of %d\n", (int)pid);

int status;
pid_t who = wait(&status);
if (WIFEXITED(status))
    printf("%d exited with %d\n", (int)who, WEXITSTATUS(status));

